// Relationships are direct, never inferred from a shared friend.
const PalaisSocial={
  pair(a,b){return [a,b].sort().join('|')},
  knows(relations,a,b){return a===b||a==='me'||b==='me'||relations.some(x=>x.key===this.pair(a,b))},
  connect(relations,members,source,reason){const next=relations.slice();for(let i=0;i<members.length;i++)for(let j=i+1;j<members.length;j++){const key=this.pair(members[i],members[j]);if(!next.some(x=>x.key===key))next.push({key,a:members[i],b:members[j],source,reason})}return next},
  canSee(relations,actor,moment){return this.knows(relations,actor,moment.author)},
  candidates(relations,roles,moment,parent=null){return roles.filter(r=>this.canSee(relations,r.id,moment)&&(!parent||this.visibleComments(relations,r.id,moment).some(c=>c.id===parent.id)))},
  visibleComments(relations,actor,moment){const all=moment.comments||[],visible=new Set(all.filter(c=>this.knows(relations,actor,c.author)).map(c=>c.id));let changed=true;while(changed){changed=false;all.forEach(c=>{if(visible.has(c.id)&&c.parentId&&!visible.has(c.parentId)){visible.delete(c.id);changed=true}})}return all.filter(c=>visible.has(c.id))},
  groupHistory(history,actor){return history.filter(m=>(m.audience||[]).includes(actor))}
};
const storedSocial=localRead('socialState',null);
let relations=storedSocial?.relations||[],feedEvents=storedSocial?.feedEvents||[],socialSettings=storedSocial?.settings||{auto:true},socialBusy=false;
if(storedSocial){groups=storedSocial.groups;moments=storedSocial.moments}
function saveSocial(){localSave('socialState',{groups,moments,relations,feedEvents,settings:socialSettings})}
function knows(a,b){return PalaisSocial.knows(relations,a,b)}
function relationshipPrompt(id){const known=relations.filter(x=>x.a===id||x.b===id).map(x=>chatLabel(x.a===id?x.b:x.a)+'（'+x.reason+'）');return '你认识的其他角色：'+(known.join('；')||'暂时没有')+'。没有在世界书明确说明或这里登记的关系，不要假装早已认识。不因认识同一个朋友而自动认识其他角色。'}
function groupSeen(r,id){return PalaisSocial.groupHistory(histories[r.id]||[],id)}
function memoryHistory(id){if(!id.startsWith('shared:'))return histories[id]||[];const actor=id.slice(7),fromGroups=groups.flatMap(g=>groupSeen(g,actor).map(m=>({...m,sender:undefined,card:undefined,source:'群聊「'+g.name+'」',content:'[群聊「'+g.name+'」] '+msgForAPI(m).content})));return [...fromGroups,...feedEvents.filter(e=>e.audience.includes(actor))].sort((a,b)=>(a.createdAt||0)-(b.createdAt||0)||String(a.id).localeCompare(String(b.id)))}
function sharedContext(id){const history=memoryHistory('shared:'+id),pending=history.length-(memories['shared:'+id]?.processed||0),summary=memoryPrompt('shared:'+id),recent=history.slice(-Math.max(20,Math.min(80,pending))).map(m=>m.content).join('\n');return [summary&&'你参与过的共同经历摘要：\n'+summary,recent&&'你见过的近期群聊与朋友圈：\n'+recent].filter(Boolean).join('\n\n')+'\n这些是你亲历的公开互动，可以在与用户的私聊中自然提起；没有参与的群聊、其他角色的私聊不能凭空知道。'}
function groupMemory(g,id){const full=histories[g.id]||[],seen=groupSeen(g,id);return full.length===seen.length?memoryPrompt(g.id):'你只能参考入群后看到的对话，不知道入群前的聊天内容。'}
function feedContext(id,m){const visible=PalaisSocial.visibleComments(relations,id,m);return '动态作者：'+(m.author==='me'?profile.name:chatLabel(m.author))+'\n动态正文：'+m.text+'\n可见评论：\n'+visible.slice(-20).map(c=>`[${c.id}] ${c.author==='me'?profile.name:chatLabel(c.author)}${c.parentId?' 回复 ['+c.parentId+']':''}：${c.text}`).join('\n')}
function feedWitness(m,c=null){return roles.filter(r=>PalaisSocial.canSee(relations,r.id,m)&&(!c||knows(r.id,c.author))).map(r=>r.id)}
function recordFeed(m,c=null){const id=c?'comment:'+c.id:'moment:'+m.id;if(feedEvents.some(e=>e.id===id))return;const parent=c?.parentId?m.comments.find(x=>x.id===c.parentId):null;feedEvents.push({id,role:'user',createdAt:c?.createdAt||m.createdAt,source:'朋友圈',audience:feedWitness(m,c).filter(actor=>!c||PalaisSocial.visibleComments(relations,actor,m).some(x=>x.id===c.id)),content:'[朋友圈] '+(c?(c.author==='me'?profile.name:chatLabel(c.author))+(parent?' 回复 '+(parent.author==='me'?profile.name:chatLabel(parent.author)):' 评论 '+(m.author==='me'?profile.name:chatLabel(m.author))+'的动态')+'：'+c.text+'\n动态正文：'+m.text.slice(0,1200)+(parent?'\n被回复的评论：'+parent.text.slice(0,500):''):'「'+(m.author==='me'?profile.name:chatLabel(m.author))+'」发布：'+m.text)});}
function migrateSocial(){let changed=!storedSocial;groups.forEach(g=>{relations=PalaisSocial.connect(relations,g.members,'group', '在群聊「'+g.name+'」中认识');(histories[g.id]||[]).forEach((m,i)=>{if(!m.audience){m.audience=g.members.slice();changed=true}if(!m.id){m.id='legacy:'+g.id+':'+i;changed=true}})});moments.forEach(m=>{(m.comments||[]).forEach((c,i)=>{if(!c.id){c.id='legacy:'+m.id+':'+i;changed=true}})});if(!storedSocial)moments.slice().reverse().forEach(m=>{recordFeed(m);(m.comments||[]).forEach(c=>recordFeed(m,c))});if(changed){saveSocial();persist()}}
function openRelationships(){const d=panel(`<form id="relationshipsForm"><h2>世界书里的原有关系</h2><p class="api-note">如果世界书设定两个角色原本就认识，可在这里登记，朋友圈也会允许他们互动。同群认识的关系会自动记录。</p><label>第一位角色<select name="first">${roles.map(r=>`<option value="${r.id}">${escapeHtml(r.name)}</option>`).join('')}</select></label><label>第二位角色<select name="second">${roles.map(r=>`<option value="${r.id}">${escapeHtml(r.name)}</option>`).join('')}</select></label><label>关系说明<input name="reason" maxlength="100" placeholder="例如：世界书中的旧友"></label><div class="actions"><button type="button" class="secondary" id="closeRelationships">关闭</button><button class="primary">登记已认识</button></div></form><div class="relationship-list">${relations.map(x=>`<p>${escapeHtml(chatLabel(x.a))} ↔ ${escapeHtml(chatLabel(x.b))}<small>${escapeHtml(x.reason)}</small></p>`).join('')||'<p>暂时还没有认识的角色。</p>'}</div>`);$('#closeRelationships').onclick=()=>d.close();$('#relationshipsForm').onsubmit=e=>{e.preventDefault();const f=e.target;if(f.first.value===f.second.value){toast('请选择不同的角色');return}const previous=relations;relations=PalaisSocial.connect(relations,[f.first.value,f.second.value],'worldbook',f.reason.value.trim()||'世界书中原本认识');try{saveSocial();d.close();openRelationships();toast('人物关系已登记')}catch(err){relations=previous;toast(err.message)}}}
async function introduceGroup(g){if(busy)return;if(g.members.every(id=>(g.introduced||[]).includes(id))){toast('大家已经介绍过自己，新成员入群后可以继续介绍');return}await sendMessage(g,'请还没有介绍过自己的成员依次做个自我介绍：说说自己的身份，以及和我的关系。只公开你愿意在群里分享的人设信息。',null,{intro:true})}
window.addEventListener('DOMContentLoaded',()=>{try{migrateSocial()}catch(err){toast('共同经历初始化未保存：'+err.message)}});
